values
  ('coding', 'Conditions', 1, 'What does this code print?', array['0', '3 2 1', '1', '2'], 2, 'Only the first true branch runs. x = 21: 21 is below 38, so it prints 1.', 40, 'coding-if-chain', '07a5a9d7ba923b55', '{"c":"int x = 21;\nif (x >= 74) {\n  printf(\"%d \", 3);\n} else if (x >= 38) {\n  printf(\"%d \", 2);\n} else {\n  printf(\"%d \", 1);\n}","cpp":"int x = 21;\nif (x >= 74) {\n  cout << 3 << \" \";\n} else if (x >= 38) {\n  cout << 2 << \" \";\n} else {\n  cout << 1 << \" \";\n}","java":"int x = 21;\nif (x >= 74) {\n  System.out.print(3 + \" \");\n} else if (x >= 38) {\n  System.out.print(2 + \" \");\n} else {\n  System.out.print(1 + \" \");\n}","python":"x = 21\nif x >= 74:\n    print(3, end=\" \")\nelif x >= 38:\n    print(2, end=\" \")\nelse:\n    print(1, end=\" \")","pseudo":"Integer x = 21\nif (x >= 74)\n  print 3\nelse if (x >= 38)\n  print 2\nelse\n  print 1\nend if"}'::jsonb),
