  ('coding', 'Loops', 2, 'What does this code print?', array['8', '3', '5', '16'], 2, 'a and b walk along the Fibonacci numbers one step per pass. Pass by pass, a is 1 → 1 → 2 → 3 → 5. After 5 passes a is 5.', 50, 'coding-fib-loop', '08b22497288c4aaf', '{"c":"int a = 0;\nint b = 1;\nfor (int i = 1; i <= 5; i++) {\n  int t = a + b;\n  a = b;\n  b = t;\n}\nprintf(\"%d \", a);","cpp":"int a = 0;\nint b = 1;\nfor (int i = 1; i <= 5; i++) {\n  int t = a + b;\n  a = b;\n  b = t;\n}\ncout << a << \" \";","java":"int a = 0;\nint b = 1;\nfor (int i = 1; i <= 5; i++) {\n  int t = a + b;\n  a = b;\n  b = t;\n}\nSystem.out.print(a + \" \");","python":"a = 0\nb = 1\nfor i in range(1, 6):\n    t = a + b\n    a = b\n    b = t\nprint(a, end=\" \")","pseudo":"Integer a = 0\nInteger b = 1\nfor i = 1 to 5\n  Integer t = a + b\n  a = b\n  b = t\nend for\nprint a"}'::jsonb),
