  ('coding', 'While Loops', 3, 'What does this code print?', array['16', '17', '18', '1'], 1, 'Even numbers are halved, odd ones become 3x + 1, until x reaches 1. That''s 17 steps.', 60, 'coding-collatz', 'cd6f788d1784d9af', '{"c":"int x = 15;\nint c = 0;\nwhile (x != 1) {\n  if (x % 2 == 0) {\n    x /= 2;\n  } else {\n    x = 3 * x + 1;\n  }\n  c += 1;\n}\nprintf(\"%d \", c);","cpp":"int x = 15;\nint c = 0;\nwhile (x != 1) {\n  if (x % 2 == 0) {\n    x /= 2;\n  } else {\n    x = 3 * x + 1;\n  }\n  c += 1;\n}\ncout << c << \" \";","java":"int x = 15;\nint c = 0;\nwhile (x != 1) {\n  if (x % 2 == 0) {\n    x /= 2;\n  } else {\n    x = 3 * x + 1;\n  }\n  c += 1;\n}\nSystem.out.print(c + \" \");","python":"x = 15\nc = 0\nwhile x != 1:\n    if x % 2 == 0:\n        x //= 2\n    else:\n        x = 3 * x + 1\n    c += 1\nprint(c, end=\" \")","pseudo":"// \"/\" is integer division: 7 / 2 = 3\n\nInteger x = 15\nInteger c = 0\nwhile (x != 1)\n  if (x mod 2 == 0)\n    x = x / 2\n  else\n    x = 3 * x + 1\n  end if\n  c = c + 1\nend while\nprint c"}'::jsonb),
