  ('coding', 'Nested Loops', 3, 'What does this code print?', array['9', '8', '0', '19'], 1, 'p stays 1 only when nothing from 2 to i − 1 divides i, so c counts the primes from 2 to 20: 2, 3, 5, 7, 11, 13, 17, 19. That''s 8.', 60, 'coding-count-primes', 'be27989b28182ccb', '{"c":"int c = 0;\nfor (int i = 2; i <= 20; i++) {\n  int p = 1;\n  for (int j = 2; j <= i - 1; j++) {\n    if (i % j == 0) {\n      p = 0;\n      break;\n    }\n  }\n  if (p == 1) {\n    c += 1;\n  }\n}\nprintf(\"%d \", c);","cpp":"int c = 0;\nfor (int i = 2; i <= 20; i++) {\n  int p = 1;\n  for (int j = 2; j <= i - 1; j++) {\n    if (i % j == 0) {\n      p = 0;\n      break;\n    }\n  }\n  if (p == 1) {\n    c += 1;\n  }\n}\ncout << c << \" \";","java":"int c = 0;\nfor (int i = 2; i <= 20; i++) {\n  int p = 1;\n  for (int j = 2; j <= i - 1; j++) {\n    if (i % j == 0) {\n      p = 0;\n      break;\n    }\n  }\n  if (p == 1) {\n    c += 1;\n  }\n}\nSystem.out.print(c + \" \");","python":"c = 0\nfor i in range(2, 21):\n    p = 1\n    for j in range(2, i):\n        if i % j == 0:\n            p = 0\n            break\n    if p == 1:\n        c += 1\nprint(c, end=\" \")","pseudo":"Integer c = 0\nfor i = 2 to 20\n  Integer p = 1\n  for j = 2 to i - 1\n    if (i mod j == 0)\n      p = 0\n      break\n    end if\n  end for\n  if (p == 1)\n    c = c + 1\n  end if\nend for\nprint c"}'::jsonb),
