  ('coding', 'While Loops', 2, 'What does this code print?', array['15 16', '28 1', '14 15', '15 15'], 3, 'i climbs by 1 and j falls by 1 each pass, so the gap of 29 closes by 2 per pass until i is no longer below j. It prints 15 15.', 50, 'coding-two-pointers', 'a7e9c421f1b437ed', '{"c":"int i = 0;\nint j = 29;\nint c = 0;\nwhile (i < j) {\n  i += 1;\n  j -= 1;\n  c += 1;\n}\nprintf(\"%d \", c);\nprintf(\"%d \", i);","cpp":"int i = 0;\nint j = 29;\nint c = 0;\nwhile (i < j) {\n  i += 1;\n  j -= 1;\n  c += 1;\n}\ncout << c << \" \";\ncout << i << \" \";","java":"int i = 0;\nint j = 29;\nint c = 0;\nwhile (i < j) {\n  i += 1;\n  j -= 1;\n  c += 1;\n}\nSystem.out.print(c + \" \");\nSystem.out.print(i + \" \");","python":"i = 0\nj = 29\nc = 0\nwhile i < j:\n    i += 1\n    j -= 1\n    c += 1\nprint(c, end=\" \")\nprint(i, end=\" \")","pseudo":"Integer i = 0\nInteger j = 29\nInteger c = 0\nwhile (i < j)\n  i = i + 1\n  j = j - 1\n  c = c + 1\nend while\nprint c\nprint i"}'::jsonb),
